#!/bin/sh
# Package a shader-slang release into crates no larger than the crates.io limit.
#
# Usage: package-shader-slang-source.sh [release-tag]
#
# The default tag is v2026.21. Set SHADER_SLANG_SOURCE_CHECKOUT to reuse a
# checkout instead of cloning. All crate versions come from workspace.package
# in the root Cargo.toml. Generated files are placed in shader-slang-src-*;
# shader-slang-src itself ties the partitions together.

set -eu

if [ "$#" -gt 1 ]; then
    echo "usage: $0 [release-tag]" >&2
    exit 2
fi

tag=${1:-v2026.21}
release=${tag#v}
case "$tag" in
    v[0-9]*) ;;
    *)
        echo "release tag must look like v2026.21: $tag" >&2
        exit 2
        ;;
esac

script_dir=$(CDPATH='' cd "$(dirname "$0")" && pwd)
root=$(CDPATH='' cd "$script_dir/.." && pwd)
version=$(awk '
    /^\[workspace\.package\]$/ { in_package = 1; next }
    /^\[/ { in_package = 0 }
    in_package && $1 == "version" {
        gsub(/["[:space:]]/, "", $3)
        print $3
        exit
    }
' "$root/Cargo.toml")
case "$version" in
    [0-9]*.[0-9]*.[0-9]*) ;;
    *)
        echo "could not read workspace.package.version from $root/Cargo.toml" >&2
        exit 1
        ;;
esac

work_dir="$root/target/source-packaging/$tag"
source_dir=${SHADER_SLANG_SOURCE_CHECKOUT:-$work_dir/checkout}
mkdir -p "$work_dir"
if [ -z "${SHADER_SLANG_SOURCE_CHECKOUT:-}" ]; then
    rm -rf "$source_dir"
    git -c core.longpaths=true clone \
        --depth 1 \
        --branch "$tag" \
        --recurse-submodules \
        --shallow-submodules \
        https://github.com/shader-slang/slang.git \
        "$source_dir"
fi
if [ ! -f "$source_dir/CMakeLists.txt" ]; then
    echo "shader-slang checkout is incomplete: $source_dir" >&2
    exit 1
fi
find "$source_dir" -name .git -prune -exec rm -rf {} +

# Only generated partition crates are removed. The aggregator is regenerated
# below, and shader-slang-dev is never touched except for its release constant.
find "$root" -mindepth 1 -maxdepth 1 -type d -name 'shader-slang-src-*' \
    -exec rm -rf {} +
mkdir -p "$root/shader-slang-src/src"

components="$work_dir/components"
: > "$components"

cat > "$root/shader-slang-src/Cargo.toml" <<EOF
[package]
name = "shader-slang-src"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
keywords.workspace = true
categories.workspace = true
description = "Vendored shader-slang $release source and build artifacts"
build = "build.rs"
readme = "README.md"

[build-dependencies]
cmake = "0.1"
tar = "0.4"
EOF

cat > "$root/shader-slang-src/src/sources.rs" <<'EOF'
// Generated by devops/package-shader-slang-source.sh.
pub const SOURCE_ARCHIVES: &[&str] = &[
EOF

cat > "$root/shader-slang-src/src/slang_version.rs" <<EOF
// Generated by devops/package-shader-slang-source.sh.
pub const SLANG_VERSION: &str = "$release";
EOF
cat > "$root/shader-slang-dev/src/slang_version.rs" <<EOF
// Generated by devops/package-shader-slang-source.sh.
pub const SLANG_VERSION: &str = "$release";
EOF
awk -v version="$version" '
    /^shader-slang-src = / {
        sub(/version = "[^"]*"/, "version = \"=" version "\"")
    }
    { print }
' "$root/shader-slang-dev/Cargo.toml" > "$root/shader-slang-dev/Cargo.toml.tmp"
mv "$root/shader-slang-dev/Cargo.toml.tmp" "$root/shader-slang-dev/Cargo.toml"

crate_suffix() {
    suffix=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr -cs 'a-z0-9' '-')
    while [ "${suffix#-}" != "$suffix" ]; do suffix=${suffix#-}; done
    while [ "${suffix%-}" != "$suffix" ]; do suffix=${suffix%-}; done
    if [ -z "$suffix" ]; then suffix=source; fi
    if [ "${#suffix}" -gt 46 ]; then
        hash=$(printf '%s' "$2" | cksum)
        hash=${hash%% *}
        suffix=$(printf '%s' "$suffix" | cut -c 1-36)
        while [ "${suffix%-}" != "$suffix" ]; do suffix=${suffix%-}; done
        suffix="$suffix-$hash"
    fi
    printf '%s\n' "$suffix"
}

write_partition() {
    suffix=$1
    shift
    crate_name="shader-slang-src-$suffix"
    crate_dir="$root/$crate_name"
    rust_name=$(printf '%s' "$crate_name" | tr '-' '_')

    mkdir -p "$crate_dir/src"
    tar -cf "$crate_dir/source.tar" -C "$source_dir" "$@"
    archive_size=$(gzip -c "$crate_dir/source.tar" | wc -c)
    archive_size=$(printf '%s' "$archive_size" | tr -d '[:space:]')

    cat > "$crate_dir/Cargo.toml" <<EOF
[package]
name = "$crate_name"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
description = "Shader Slang $release source partition: $*"
include = ["source.tar", "src/lib.rs"]
EOF
    cat > "$crate_dir/src/lib.rs" <<'EOF'
//! Source archive consumed by the `shader-slang-src` build script.

/// Absolute path to this crate's shader-slang source archive.
pub const SOURCE_ARCHIVE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/source.tar");
EOF

    printf '%s\n' "$crate_name" >> "$components"
    printf '    %s::SOURCE_ARCHIVE,\n' "$rust_name" >> "$root/shader-slang-src/src/sources.rs"
    partition_suffix=$suffix
    partition_size=$archive_size
}

# Create one partition, recursively splitting directories whose gzip-compressed
# archive exceeds 8 MiB. The final packaged .crate is checked against 10 MiB.
emit_path() {
    suffix=$(crate_suffix "$1" "$2")
    write_partition "$suffix" "$2"
    if [ "$partition_size" -le 8388608 ]; then
        return
    fi

    rm -rf "$root/shader-slang-src-$partition_suffix"
    # Remove the provisional entry; children replace it.
    grep -v -F -x "shader-slang-src-$partition_suffix" "$components" > "$components.new"
    mv "$components.new" "$components"
    : > "$root/shader-slang-src/src/sources.rs.tmp"
    printf '%s\n' '// Generated by devops/package-shader-slang-source.sh.' \
        'pub const SOURCE_ARCHIVES: &[&str] = &[' >> "$root/shader-slang-src/src/sources.rs.tmp"
    while IFS= read -r existing; do
        rust_name=$(printf '%s' "$existing" | tr '-' '_')
        printf '    %s::SOURCE_ARCHIVE,\n' "$rust_name" >> "$root/shader-slang-src/src/sources.rs.tmp"
    done < "$components"
    mv "$root/shader-slang-src/src/sources.rs.tmp" "$root/shader-slang-src/src/sources.rs"

    if [ ! -d "$source_dir/$2" ]; then
        echo "one source file exceeds the partition threshold: $2" >&2
        exit 1
    fi
    for child in "$source_dir/$2"/* "$source_dir/$2"/.[!.]* "$source_dir/$2"/..?*; do
        if [ ! -e "$child" ] && [ ! -L "$child" ]; then continue; fi
        emit_path "$1-${child##*/}" "$2/${child##*/}"
    done
}

# Root files form the core crate; top-level directories retain their names.
set --
for path in "$source_dir"/* "$source_dir"/.[!.]* "$source_dir"/..?*; do
    if [ -f "$path" ] || [ -L "$path" ]; then
        set -- "$@" "${path##*/}"
    fi
done
write_partition core "$@"

for path in "$source_dir"/* "$source_dir"/.[!.]* "$source_dir"/..?*; do
    if [ ! -d "$path" ]; then continue; fi
    name=${path##*/}
    relative=$name
    if [ "$name" = external ]; then
        set --
        for child in "$path"/* "$path"/.[!.]* "$path"/..?*; do
            if [ -f "$child" ] || [ -L "$child" ]; then
                set -- "$@" "external/${child##*/}"
            fi
        done
        write_partition external-core "$@"
        for child in "$path"/* "$path"/.[!.]* "$path"/..?*; do
            if [ -d "$child" ]; then
                emit_path "external-${child##*/}" "external/${child##*/}"
            fi
        done
    else
        emit_path "$name" "$relative"
    fi
done

printf '%s\n' '];' >> "$root/shader-slang-src/src/sources.rs"
while IFS= read -r crate_name; do
    cat >> "$root/shader-slang-src/Cargo.toml" <<EOF
$crate_name = { path = "../$crate_name", version = "=$version" }
EOF
done < "$components"

# Package each partition to measure exactly what crates.io will receive.
while IFS= read -r crate_name; do
    cargo package --quiet --allow-dirty --no-verify \
        --manifest-path "$root/$crate_name/Cargo.toml"
    package="$root/target/package/$crate_name-$version.crate"
    package_size=$(wc -c < "$package")
    package_size=$(printf '%s' "$package_size" | tr -d '[:space:]')
    if [ "$package_size" -gt 10485760 ]; then
        echo "$crate_name is $package_size bytes; crates.io allows at most 10485760" >&2
        exit 1
    fi
    printf '%-64s %10s bytes\n' "$crate_name" "$package_size"
done < "$components"

printf 'Packaged shader-slang %s as crate version %s (%s partitions).\n' \
    "$release" "$version" "$(wc -l < "$components" | tr -d '[:space:]')"
